export const difficultyLabels = ['Muy fácil', 'Fácil', 'Intermedio', 'Difícil', 'Experto'];

export const questions = groups.flatMap(([category, text], groupIndex) => text.trim().split('\n').map((line, questionIndex) => {
  const [question, answer, ...rest] = line.split('|');
  const explanation = rest.pop();
  return { id: 0, category, difficulty: difficultyByGroup[groupIndex][questionIndex], question, answer, options: [answer, ...rest], explanation };
})).map((item, i) => ({ ...item, id: i + 1 }));

// El tema varía dentro de cada nivel; la dificultad nunca disminuye.
const warmup = [68, 67, 55, 88, 96, 100, 113, 114, 115, 116];
export const orderedQuestions = [...questions].sort((a, b) => {
  if (a.difficulty !== b.difficulty) return a.difficulty - b.difficulty;
  const aWarmup = warmup.indexOf(a.id), bWarmup = warmup.indexOf(b.id);
  if (aWarmup !== -1 || bWarmup !== -1) return (aWarmup === -1 ? 1000 : aWarmup) - (bWarmup === -1 ? 1000 : bWarmup);
  return ((a.id - 1) % 25) - ((b.id - 1) % 25) || a.id - b.id;
});
